CREATE TABLE `devrebel-big-query-database.Pace.Pace_Property`
(
  property_code STRING OPTIONS(description="Property code"),
  property_name STRING OPTIONS(description="Property name"),
  dow STRING OPTIONS(description="Day of week"),
  stay_date DATE OPTIONS(description="Filters the information and consumed revenue and other metrics based on the guest's stay dates."),
  stay_date_py DATE OPTIONS(description="Filters the information and consumed revenue and other metrics based on the guest's stay dates."),
  rms_fct INT64 OPTIONS(description="Total number of forecasted room nights"),
  rms_fct_py INT64 OPTIONS(description="Total number of forecasted room nights"),
  rms_fct_trn INT64 OPTIONS(description="Total number of forecasted transient room nights"),
  rms_fct_trn_py INT64 OPTIONS(description="Total number of forecasted transient room nights"),
  rms_fct_grp INT64 OPTIONS(description="Total number of forecasted group room nights."),
  rms_fct_grp_py INT64 OPTIONS(description="Total number of forecasted group room nights."),
  adr_fct FLOAT64 OPTIONS(description="System-generated ADR forecast refers to the projected average daily rate (ADR) calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  adr_fct_py FLOAT64 OPTIONS(description="System-generated ADR forecast refers to the projected average daily rate (ADR) calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  rev_fct FLOAT64 OPTIONS(description="System-Generated Rooms Revenue Forecast refers to the projected rooms revnue calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  rev_fct_py FLOAT64 OPTIONS(description="System-Generated Rooms Revenue Forecast refers to the projected rooms revnue calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  projected_rms INT64 OPTIONS(description="Projected room nights based on the hotel’s uploaded forecast, assessed separately from the system's projected room nights."),
  projected_rms_py INT64 OPTIONS(description="Projected room nights based on the hotel’s uploaded forecast, assessed separately from the system's projected room nights."),
  revpar_fct FLOAT64 OPTIONS(description="System-Generated RevPAR Forecast refers to the projected RevPAR calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  revpar_fct_py FLOAT64 OPTIONS(description="System-Generated RevPAR Forecast refers to the projected RevPAR calculated by hotel revenue management or forecasting systems. These predictions are based on factors such as historical data, booking patterns, market trends, and pricing strategies. They assist hotels in forecasting future revenue performance and making informed pricing decisions."),
  rms INT64 OPTIONS(description="Competitor number of rooms"),
  rms_py INT64 OPTIONS(description="Competitor number of rooms"),
  rms_stly INT64 OPTIONS(description="Rooms on the books same time prior year"),
  rms_st2y INT64 OPTIONS(description="Total group room nights on the books as of two years ago"),
  rms_st19 INT64 OPTIONS(description="Rooms on the books same time 2019"),
  adr FLOAT64 OPTIONS(description="Average Dollar Rate (ADR) represents the average income generated per room sold during a given timeframe. It is determined by dividing the total room revenue by the number of rooms sold."),
  adr_py FLOAT64 OPTIONS(description="Average Dollar Rate (ADR) represents the average income generated per room sold during a given timeframe. It is determined by dividing the total room revenue by the number of rooms sold."),
  rev FLOAT64 OPTIONS(description="Total room revenue"),
  rev_py FLOAT64 OPTIONS(description="Total room revenue"),
  rev_stly FLOAT64 OPTIONS(description="Total room revenue on the books as of the same time prior year"),
  rev_st2y FLOAT64 OPTIONS(description="Total room revenue on the books as of two years ago"),
  rev_st19 FLOAT64 OPTIONS(description="Total room revenue on the books as of the same time in 2019"),
  revpar FLOAT64 OPTIONS(description="Competitive set revenue per available room"),
  revpar_py FLOAT64 OPTIONS(description="Competitive set revenue per available room"),
  rms_grp INT64 OPTIONS(description="Total group room nights on the books."),
  rms_grp_py INT64 OPTIONS(description="Total group room nights on the books."),
  rms_grp_stly INT64 OPTIONS(description="Total group room revenue on the books as of the same time prior year."),
  rms_grp_st2y INT64 OPTIONS(description="Total group room nights on the books as of two years ago."),
  rms_grp_st19 INT64 OPTIONS(description="Total group room nights on the books as of the same time in 2019."),
  rms_trn INT64 OPTIONS(description="Total transient room nights on the books."),
  rms_trn_py INT64 OPTIONS(description="Total transient room nights on the books."),
  rms_trn_stly INT64 OPTIONS(description="Total transient room revenue on the books as of the same time prior year"),
  rms_trn_st2y INT64 OPTIONS(description="Total transient room nights on the books as of two years ago"),
  rms_trn_st19 INT64 OPTIONS(description="Total transient room nights on the books as of the same time in 2019"),
  arrivals INT64 OPTIONS(description="The total number of arrivals and the guests or bookings scheduled to check in within the defined period."),
  arrivals_py INT64 OPTIONS(description="The total number of arrivals and the guests or bookings scheduled to check in within the defined period."),
  departures INT64 OPTIONS(description="The total number of departures and the guests or bookings scheduled to check out within the defined period."),
  projected_rev FLOAT64 OPTIONS(description="Projected revenue based on the hotel’s uploaded forecast, assessed separately from the system's projected revenue."),
  projected_rev_py FLOAT64 OPTIONS(description="Projected revenue based on the hotel’s uploaded forecast, assessed separately from the system's projected revenue."),
  departures_py INT64 OPTIONS(description="The total number of departures and the guests or bookings scheduled to check out within the defined period."),
  rms_ooo INT64 OPTIONS(description="Out of order rooms current year"),
  rms_ooo_py INT64 OPTIONS(description="Out of order rooms current year"),
  rms_other INT64 OPTIONS(description="Room revenue other current year"),
  rms_other_py INT64 OPTIONS(description="Room revenue other current year"),
  cx INT64 OPTIONS(description="The total number of reservations canceled during a given time frame. This includes all cancellations, regardless of when the bookings were initially made or the intended stay dates."),
  no_show_py INT64 OPTIONS(description="Total No-Shows and refers to guests with confirmed reservations who neither arrived nor canceled their booking restuling in lost occupancy and missed revenue opportunities."),
  no_show INT64 OPTIONS(description="Total No-Shows and refers to guests with confirmed reservations who neither arrived nor canceled their booking restuling in lost occupancy and missed revenue opportunities."),
  cx_py INT64 OPTIONS(description="The total number of reservations canceled during a given time frame. This includes all cancellations, regardless of when the bookings were initially made or the intended stay dates."),
  bar STRING OPTIONS(description="The property's current best flexible rate (BAR)—the standard, publicly available rate with the most flexible booking conditions"),
  lrv_py FLOAT64 OPTIONS(description="The current last room value (lrv) for the hotel or hurdle rate based on the highest potential revenue a hotel can earn from selling its final available room. This value represents the maximum rate achievable, especially during times of peak demand."),
  lrv FLOAT64 OPTIONS(description="The current last room value (lrv) for the hotel or hurdle rate based on the highest potential revenue a hotel can earn from selling its final available room. This value represents the maximum rate achievable, especially during times of peak demand."),
  overbooking_py INT64 OPTIONS(description="Overbooking current year"),
  overbooking INT64 OPTIONS(description="Overbooking current year"),
  wash_pct FLOAT64 OPTIONS(description="The wash percentage refers to the portion of initially anticipated demand—such as group or block bookings—that does not come to fruition (e.g., due to cancellations, no-shows, or unused room blocks). This metric aids in accurately forecasting actual pickup and effectively managing the risk of overbooking."),
  wash_pct_py FLOAT64 OPTIONS(description="The wash percentage refers to the portion of initially anticipated demand—such as group or block bookings—that does not come to fruition (e.g., due to cancellations, no-shows, or unused room blocks). This metric aids in accurately forecasting actual pickup and effectively managing the risk of overbooking."),
  special_event STRING OPTIONS(description="Special event current year"),
  special_event_py STRING OPTIONS(description="Special event current year"),
  demand INT64 OPTIONS(description="Demand is the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  demand_py INT64 OPTIONS(description="Demand is the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  unconstrained_demand_trn_py INT64 OPTIONS(description="Transient unconstrained demand reflects the total potential demand for hotel rooms, assuming no limitations on availability, pricing, or booking restrictions. It indicates how many rooms could have been sold if there were unlimited capacity and no barriers to booking"),
  unconstrained_demand_trn INT64 OPTIONS(description="Transient unconstrained demand reflects the total potential demand for hotel rooms, assuming no limitations on availability, pricing, or booking restrictions. It indicates how many rooms could have been sold if there were unlimited capacity and no barriers to booking"),
  constrained_demand_grp_py INT64 OPTIONS(description="Group constrained demand refers to the level of guest demand that can be accommodated within a hotel’s available inventory and operational restrictions. It represents the actual number of rooms sold when factors like capacity, pricing, or stay rules limit the fulfillment of demand."),
  constrained_demand_grp INT64 OPTIONS(description="Group constrained demand refers to the level of guest demand that can be accommodated within a hotel’s available inventory and operational restrictions. It represents the actual number of rooms sold when factors like capacity, pricing, or stay rules limit the fulfillment of demand."),
  remaining_capacity_py INT64 OPTIONS(description="Remaining capacity is the number of unsold rooms still available for a specific date or time period. It is determined by subtracting the number of rooms already sold or reserved from the total number of available rooms."),
  remaining_capacity INT64 OPTIONS(description="Remaining capacity is the number of unsold rooms still available for a specific date or time period. It is determined by subtracting the number of rooms already sold or reserved from the total number of available rooms."),
  physical_capacity_py INT64 OPTIONS(description="The total number of rooms available for sale represents the property's fixed maximum inventory. This count excludes any rooms that are out of order."),
  physical_capacity INT64 OPTIONS(description="The total number of rooms available for sale represents the property's fixed maximum inventory. This count excludes any rooms that are out of order."),
  projected_adr FLOAT64 OPTIONS(description="Projected ADR based on the hotel’s uploaded forecast, assessed separately from the system's projected ADR."),
  projected_adr_py FLOAT64 OPTIONS(description="Projected ADR based on the hotel’s uploaded forecast, assessed separately from the system's projected ADR."),
  sys_demand_py FLOAT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  sys_demand INT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  sys_demand_grp INT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  sys_demand_trn FLOAT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  sys_demand_trn_py FLOAT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  sys_demand_grp_py INT64 OPTIONS(description="System-generated demand represents the total number of guests attempting to book rooms within a specific timeframe. It includes both confirmed bookings and missed opportunities due to limitations, such as restricted availability or other constraints."),
  snapshot_date DATE OPTIONS(description="Filters the date in which the data was collected."),
  ingested_timestamp TIMESTAMP OPTIONS(description="Datetime of data ingestion"),
  sent_to_big_query BOOL OPTIONS(description="Sent to big query"),
  date_sent_to_big_query TIMESTAMP OPTIONS(description="Date when the data was sent to biq query")
)
PARTITION BY stay_date
CLUSTER BY property_code, snapshot_date
OPTIONS(
  partition_expiration_days=60.0
);